import sys

s = sys.stdin.read()
flipped = ''.join(ch.swapcase() for ch in s)

out = []
for ch in flipped:
    if ch.lower() in 'aeiou':
        out.append(chr(ord(ch) + 2))
    else:
        out.append(ch)

sys.stdout.write(''.join(out))
